style.css:
/* soft pink universal theme */

:root{
  -pink-main:#f7d6dc;
  -pink-soft:#fdf6f8;
  -pink-accent:#e7a3ad;
  -pink-dark:#c77482;
}

/* page background + text */

body{
  background-color: var(--pink-soft) !important;
  color:#5a4a4c !important;
  font-family: Georgia, serif !important;
  font-size:16px !important;
}

/* links */

a{
  color: var(--pink-dark) !important;
}

a:hover{
  color:#a85464 !important;
}

/* buttons */

button,
input[type="button"],
input[type="submit"]{
  background-color: var(--pink-main) !important;
  border:1px solid #e6b8c0 !important;
  color:#5a4a4c !important;
  border-radius:8px !important;
}

button:hover{
  background-color: var(--pink-accent) !important;
}

/* input fields */

input,
textarea,
select{
  background:#fff7f9 !important;
  border:1px solid #e6b8c0 !important;
  color:#5a4a4c !important;
}

/* cards / panels */

div,
section,
article{
  border-radius:8px;
}

/* scrollbars */

::-webkit-scrollbar{
  width:10px;
}

::-webkit-scrollbar-track{
  background:#fdecef;
}

::-webkit-scrollbar-thumb{
  background:#e7a3ad;
  border-radius:10px;
}

::-webkit-scrollbar-thumb:hover{
  background:#d48b97;
}

/* selection color */

::selection{
  background:#f3c6cf;
}

/* images slightly softened */

img{
  filter: saturate(0.95) brightness(1.02);
}
